import { integer, snakeCase, text, type AnySQLiteColumn } from 'drizzle-orm/sqlite-core'

/** Better Auth's tables for this app, referencing the app-owned users table. */
export function authSchema(users: { id: AnySQLiteColumn }) {
  const session = snakeCase.table('session', {
    id: text().primaryKey().$defaultFn(() => crypto.randomUUID()),
    expiresAt: integer({ mode: 'timestamp_ms' }).notNull(),
    token: text().notNull().unique(),
    createdAt: integer({ mode: 'timestamp_ms' }).notNull().$defaultFn(() => new Date()),
    updatedAt: integer({ mode: 'timestamp_ms' }).notNull(),
    ipAddress: text(),
    userAgent: text(),
    userId: text().notNull().references((): AnySQLiteColumn => users.id, { onDelete: 'cascade' }),
  })

  const account = snakeCase.table('account', {
    id: text().primaryKey().$defaultFn(() => crypto.randomUUID()),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text().notNull().references((): AnySQLiteColumn => users.id, { onDelete: 'cascade' }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: integer({ mode: 'timestamp_ms' }),
    refreshTokenExpiresAt: integer({ mode: 'timestamp_ms' }),
    scope: text(),
    password: text(),
    createdAt: integer({ mode: 'timestamp_ms' }).notNull().$defaultFn(() => new Date()),
    updatedAt: integer({ mode: 'timestamp_ms' }).notNull(),
  })

  const verification = snakeCase.table('verification', {
    id: text().primaryKey().$defaultFn(() => crypto.randomUUID()),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: integer({ mode: 'timestamp_ms' }).notNull(),
    createdAt: integer({ mode: 'timestamp_ms' }).notNull().$defaultFn(() => new Date()),
    updatedAt: integer({ mode: 'timestamp_ms' }).notNull().$defaultFn(() => new Date()),
  })

  return { session, account, verification }
}
